{
	global $mybb, $db, $lang;

	if(!$input)
	{
		$input = $mybb->input;
	}

	if(!is_array($input['conditions']))
	{
		$input['conditions'] = unserialize($input['conditions']);
	}

	if(!is_array($input['profile_fields']))
	{
