					$md5 = md5($contents);

					// Does it match any of our hashes (unix/windows new lines taken into consideration with the hashes)
					if(!in_array($md5, $checksums[$file_path]))
					{						
						$bad_verify_files[] = array("status" => "changed", "path" => $file_path);
