			{
			    $hideinfo = true;
			}

			if($permissions['canonlyviewownthreads'] == 1)
			{
				$hideinfo = true;

				// If we only see our own threads, find out if there's a new post in one of them so the lightbulb shows
				if(!is_array($private_forums))
